-- Catálogo canônico do Rework. Não importa contas, personagens ou sessões.

create table if not exists public.v2_rework_catalog_backups (
  migration_key text not null,
  content_id uuid not null references public.v2_content(id) on delete cascade,
  content_type text not null,
  slug text not null,
  name text not null,
  status text not null,
  payload jsonb not null,
  published_at timestamptz,
  backed_up_at timestamptz not null default now(),
  primary key (migration_key, content_id)
);

revoke all on public.v2_rework_catalog_backups from public, anon, authenticated;

insert into public.v2_rework_catalog_backups
  (migration_key, content_id, content_type, slug, name, status, payload, published_at)
select
  '20260919120000_rework_classes_races_v2', id, content_type, slug, name, status, payload, published_at
from public.v2_content
where content_type in ('class', 'race')
on conflict (migration_key, content_id) do nothing;

