ico","range":"Pessoal","area":"3x3","adjustment":"+15% no efeito principal desta versão"}},{"id":"barbaro-4-guardiao-tribal","pathId":"guardiao-tribal","pathName":"Guardião Tribal","name":"Terremoto: Guardião Tribal","description":"Ao dominar Guardião Tribal, a técnica assume uma nova forma: Terremoto reduz dano inimigo. O efeito favorece proteção de aliados sem apagar a identidade original da habilidade.","unlockLevel":21,"combat":{"power":"145% [FOR]","damageType":"Físico","range":"Pessoal","area":"3x3","adjustment":"+20% no efeito principal desta versão"}}]},{"id":"barbaro-5","iconUrl":"/assets/skills/classes/barbaro/5.webp","kind":"Suprema","name":"Ira dos Ancestrais","description":"Entra em frenesi e age novamente após cada primeira eliminação.","unlockLevel":13,"cooldown":"11 turnos","combat":{"power":"200% [FOR]","damageType":"Físico","range":"Pessoal","area":"3x3","duration":"3 Turnos"},"variants":[{"id":"barbaro-5-berserker","pathId":"berserker","pathName":"Berserker","name":"Ira dos Ancestrais: Berserker","description":"Ao dominar Berserker, a técnica assume uma nova forma: Frenesi mantém HP mínimo enquanto durar. O efeito favorece risco e dano sem apagar a identidade original da habilidade.","unlockLevel":23,"combat":{"power":"200% [FOR]","damageType":"Físico","range":"Pessoal","area":"3x3","duration":"3 Turnos","adjustment":"+10% no efeito principal desta versão"}},{"id":"barbaro-5-quebra-linhas","pathId":"quebra-linhas","pathName":"Quebra-Linhas","name":"Ira dos Ancestrais: Quebra-Linhas","description":"Ao dominar Quebra-Linhas, a técnica assume uma nova forma: Suprema empurra inimigos a cada golpe. O efeito favorece empurrões e área sem apagar a identidade original da habilidade.","unlockLevel":25,"combat":{"power":"200% [FOR]","damageType":"Físico","range":"Pessoal","area":"3x3","duration":"3 Turnos","adjustment":"+15% no efeito principal desta versão"}},{"id":"barbaro-5-guardiao-tribal","pathId":"guardiao-tribal","pathName":"Guardião Tribal","name":"