  ('class', 'monge', 'Monge', '{"contractVersion":2,"id":"monge","name":"Monge","sigil":"☯","role":"Combos • Mobilidade","description":"Encadeia técnicas, controla distância e converte disciplina em sequências precisas.","abilities":[{"id":"monge-0","iconUrl":"/assets/skills/classes/monge/0.webp","kind":"Passiva","name":"Fluxo Marcial","description":"Usar ações diferentes mantém o combo; repetir a mesma ação encerra a sequência.","unlockLevel":1,"cooldown":"Sem recarga","combat":{"range":"Pessoal","area":"1"},"variants":[{"id":"monge-0-punho-de-ferro","pathId":"punho-de-ferro","pathName":"Punho de Ferro","name":"Fluxo Marcial: Punho de Ferro","description":"Ao dominar Punho de Ferro, a técnica assume uma nova forma: O terceiro golpe diferente da sequência ignora 20% da DEF. O efeito favorece dano e quebra sem apagar a identidade original da habilidade.","unlockLevel":5,"combat":{"range":"Pessoal","area":"1","adjustment":"+1 Turno de duração quando aplicável"}},{"id":"monge-0-vento-livre","pathId":"vento-livre","pathName":"Vento Livre","name":"Fluxo Marcial: Vento Livre","description":"Ao dominar Vento Livre, a técnica assume uma nova forma: Após duas ações diferentes, recebe 1 bloco de movimento. O efeito favorece mobilidade e alcance sem apagar a identidade original da habilidade.","unlockLevel":6,"combat":{"range":"Pessoal","area":"1","adjustment":"+1 bloco de alcance ou deslocamento"}},{"id":"monge-0-templo-vivo","pathId":"templo-vivo","pathName":"Templo Vivo","name":"Fluxo Marcial: Templo Vivo","description":"Ao dominar Templo Vivo, a técnica assume uma nova forma: Após duas ações diferentes, reduz em 15% o próximo dano recebido. O efeito favorece defesa e suporte sem apagar a identidade original da habilidade.","unlockLevel":5,"combat":{"range":"Pessoal","area":"1","adjustment":"+15% na intensidade do benefício ou penalidade"}}]},{"id":"monge-1","iconUrl":"/assets/skills/classes/monge/1.webp","kind":"Ataque básico","name":"Sequência Marcial","description":"Comb