OR]","damageType":"Físico","range":"4","area":"Linha de 4","adjustment":"+10% no efeito principal desta versão"}},{"id":"ninja-2-sombra","pathId":"sombra","pathName":"Sombra","name":"Passo Relâmpago: Sombra","description":"Ao dominar Sombra, a técnica assume uma nova forma: Passo ganha alcance. O efeito favorece ocultação e reposição sem apagar a identidade original da habilidade.","unlockLevel":12,"combat":{"power":"120% [FOR]","damageType":"Físico","range":"4","area":"Linha de 4","adjustment":"+15% no efeito principal desta versão"}},{"id":"ninja-2-tecnicas","pathId":"tecnicas","pathName":"Técnicas","name":"Passo Relâmpago: Técnicas","description":"Ao dominar Técnicas, a técnica assume uma nova forma: Passo reduz movimento. O efeito favorece controle por técnicas sem apagar a identidade original da habilidade.","unlockLevel":11,"combat":{"power":"120% [FOR]","damageType":"Físico","range":"4","area":"Linha de 4","adjustment":"+20% no efeito principal desta versão"}}]},{"id":"ninja-3","iconUrl":"/assets/skills/classes/ninja/3.webp","kind":"Habilidade 2","name":"Clone de Substituição","description":"Troca de lugar ao receber o próximo ataque.","unlockLevel":4,"cooldown":"5 turnos","combat":{"power":"90% [FOR]","damageType":"Físico","range":"Pessoal","area":"1","duration":"Até o próximo ataque"},"variants":[{"id":"ninja-3-lamina","pathId":"lamina","pathName":"Lâmina","name":"Clone de Substituição: Lâmina","description":"Ao dominar Lâmina, a técnica assume uma nova forma: Clone contra-ataca. O efeito favorece explosão física sem apagar a identidade original da habilidade.","unlockLevel":14,"combat":{"power":"90% [FOR]","damageType":"Físico","range":"Pessoal","area":"1","duration":"Até o próximo ataque","adjustment":"+10% no efeito principal desta versão"}},{"id":"ninja-3-sombra","pathId":"sombra","pathName":"Sombra","name":"Clone de Substituição: Sombra","description":"Ao dominar Sombra, a técnica assume uma nova forma: Clone pode ser ativado manualmente. O efeito favo