  ('class', 'paladino', 'Paladino', '{"contractVersion":2,"id":"paladino","name":"Paladino","sigil":"✠","role":"Tanque • Suporte sagrado","description":"Protege aliados na linha de frente e converte defesa em julgamento sagrado.","abilities":[{"id":"paladino-0","iconUrl":"/assets/skills/classes/paladino/0.webp","kind":"Passiva","name":"Juramento","description":"Escolha proteger um aliado; a primeira vez que ele sofrer dano a cada rodada, recebe Barreira de 8% do HP máximo.","unlockLevel":1,"cooldown":"Sem recarga","combat":{"range":"Pessoal","area":"1"},"variants":[{"id":"paladino-0-templario","pathId":"templario","pathName":"Templário","name":"Juramento: Templário","description":"Ao dominar Templário, a técnica assume uma nova forma: Enquanto o aliado protegido estiver próximo, ambos recebem 15% de DEF. O efeito favorece defesa de linha sem apagar a identidade original da habilidade.","unlockLevel":5,"combat":{"range":"Pessoal","area":"1","adjustment":"+1 Turno de duração quando aplicável"}},{"id":"paladino-0-justicar","pathId":"justicar","pathName":"Justicar","name":"Juramento: Justicar","description":"Ao dominar Justicar, a técnica assume uma nova forma: Após proteger um aliado, o próximo golpe sagrado causa 20% mais dano. O efeito favorece dano sagrado sem apagar a identidade original da habilidade.","unlockLevel":6,"combat":{"range":"Pessoal","area":"1","adjustment":"+1 bloco de alcance ou deslocamento"}},{"id":"paladino-0-arauto-da-luz","pathId":"arauto-da-luz","pathName":"Arauto da Luz","name":"Juramento: Arauto da Luz","description":"Ao dominar Arauto da Luz, a técnica assume uma nova forma: Barreiras e curas no aliado protegido recebem 20% de potência. O efeito favorece cura e apoio sem apagar a identidade original da habilidade.","unlockLevel":5,"combat":{"range":"Pessoal","area":"1","adjustment":"+15% na intensidade do benefício ou penalidade"}}]},{"id":"paladino-1","iconUrl":"/assets/skills/classes/paladino/1.webp","kind":"Ataque básico","name":"Golpe Co