  ('race', 'aengel', 'Aengel', '{"contractVersion":2,"id":"aengel","name":"Aengel","epithet":"Herdeiros da Alvorada","sigil":"✦","description":"Protetores celestiais que dominam luz, barreiras e os céus do campo de batalha.","baseStats":{"FOR":20,"INT":55,"DEF":40,"RES":40,"HP":460,"INI":10},"powers":[{"id":"aengel-0","iconUrl":"/assets/skills/races/aengel/0.webp","unlockLevel":1,"name":"Luz Celestial","kind":"Característica","description":"No início do combate, escolha a si ou um aliado. O alvo recebe uma Barreira de 100 + 40% da INT do Aengel. Uma vez por combate."},{"id":"aengel-1","iconUrl":"/assets/skills/races/aengel/1.webp","unlockLevel":1,"name":"Julgamento da Alvorada","kind":"Habilidade","description":"Causa 80% da INT como dano mágico de Luz aos inimigos na área.","cooldown":"6 turnos","range":"5","area":"3×3"},{"id":"aengel-2","iconUrl":"/assets/skills/races/aengel/2.webp","unlockLevel":5,"name":"Voo da Alvorada","kind":"Habilidade","description":"Voe até uma célula livre, ignorando unidades e obstáculos baixos. Ao pousar, receba 20% de redução de dano até o próximo turno.","cooldown":"5 turnos","range":"4"}]}'::jsonb),
  ('race', 'draconato', 'Draconato', '{"contractVersion":2,"id":"draconato","name":"Draconato","epithet":"Sangue dos Dragões","sigil":"◆","description":"Descendentes de linhagens dracônicas, resistentes e capazes de dominar território com poder elemental.","baseStats":{"FOR":55,"INT":25,"DEF":50,"RES":35,"HP":620,"INI":7},"powers":[{"id":"draconato-0","iconUrl":"/assets/skills/races/draconato/0.webp","unlockLevel":1,"name":"Escamas Ancestrais","kind":"Característica","description":"O primeiro ataque sofrido a cada rodada causa 15% menos dano. Ataques que ignoram defesa reduzem apenas metade desse valor."},{"id":"draconato-1","iconUrl":"/assets/skills/races/draconato/1.webp","unlockLevel":1,"name":"Sopro Dracônico","kind":"Habilidade","description":"Expele energia dracônica em cone, causando 70% da FOR + 30% da INT como dano mágico.","cooldown":"5 turnos","range":"3","area":"Cone"},{"id":"draconato-2","iconUrl":"/assets/skills/races/draconato/2.webp","unlockLevel":5,"name":"Domínio do Dragão","kind":"Habilidade","description":"Golpeia o chão e empurra inimigos adjacentes 2 células. Alvos que colidirem com obstáculo sofrem dano físico adicional.","cooldown":"6 turnos","range":"Próprio","area":"Adjacente"}]}'::jsonb),
