  ('race', 'fada', 'Fada', '{"contractVersion":2,"id":"fada","name":"Fada","epithet":"Centelhas do Véu","sigil":"✧","description":"Seres feéricos frágeis, velozes e extraordinariamente afinados com magia e encantamentos.","baseStats":{"FOR":15,"INT":60,"DEF":20,"RES":50,"HP":320,"INI":16},"powers":[{"id":"fada-0","iconUrl":"/assets/skills/races/fada/0.webp","unlockLevel":1,"name":"Corpo Feérico","kind":"Característica","description":"Pode atravessar células ocupadas por unidades durante o movimento e recebe 20% menos dano de ataques em área."},{"id":"fada-1","iconUrl":"/assets/skills/races/fada/1.webp","unlockLevel":1,"name":"Pó Restaurador","kind":"Habilidade","description":"Remove um efeito negativo do alvo e restaura 40 + 25% da INT em HP.","cooldown":"5 turnos","range":"4","area":"1 alvo"},{"id":"fada-2","iconUrl":"/assets/skills/races/fada/2.webp","unlockLevel":5,"name":"Salto entre Véus","kind":"Habilidade","description":"Teleporte-se para uma célula visível. A próxima habilidade de suporte usada até o fim do turno recebe 15% de potência.","cooldown":"5 turnos","range":"5"}]}'::jsonb),
