  ('race', 'leonis', 'Leonis', '{"contractVersion":2,"id":"leonis","name":"Leonis","epithet":"Orgulho da Savana","sigil":"✺","description":"Caçadores nobres que marcam presas, pressionam a linha de frente e protegem seu território.","baseStats":{"FOR":52,"INT":20,"DEF":45,"RES":30,"HP":580,"INI":11},"powers":[{"id":"leonis-0","iconUrl":"/assets/skills/races/leonis/0.webp","unlockLevel":1,"name":"Instinto do Alfa","kind":"Característica","description":"Ao causar dano pela primeira vez, marque o inimigo como Presa. Contra a Presa, ganhe 10% de dano e 1 de movimento."},{"id":"leonis-1","iconUrl":"/assets/skills/races/leonis/1.webp","unlockLevel":1,"name":"Rugido Soberano","kind":"Habilidade","description":"Inimigos próximos causam 15% menos dano por 2 turnos e são forçados a revelar sua posição.","cooldown":"6 turnos","range":"Próprio","area":"Raio 2"},{"id":"leonis-2","iconUrl":"/assets/skills/races/leonis/2.webp","unlockLevel":5,"name":"Bote do Predador","kind":"Habilidade","description":"Salte sobre um inimigo e cause 90% da FOR como dano físico. O alcance aumenta em 1 contra a Presa.","cooldown":"5 turnos","range":"4","area":"1 alvo"}]}'::jsonb),
