  ('race', 'orc', 'Orc', '{"contractVersion":2,"id":"orc","name":"Orc","epithet":"Filhos da Guerra","sigil":"⬙","description":"Guerreiros de força brutal, difíceis de derrubar e capazes de romper formações.","baseStats":{"FOR":60,"INT":15,"DEF":48,"RES":25,"HP":650,"INI":6},"powers":[{"id":"orc-0","iconUrl":"/assets/skills/races/orc/0.webp","unlockLevel":1,"name":"Recusar a Morte","kind":"Característica","description":"Uma vez por combate, ao receber dano fatal, permaneça com 1 HP e ganhe 25% de redução de dano até o próximo turno."},{"id":"orc-1","iconUrl":"/assets/skills/races/orc/1.webp","unlockLevel":1,"name":"Golpe Demolidor","kind":"Habilidade","description":"Causa 100% da FOR como dano físico e destrói 25% das Barreiras atuais do alvo antes do dano.","cooldown":"5 turnos","range":"1","area":"1 alvo"},{"id":"orc-2","iconUrl":"/assets/skills/races/orc/2.webp","unlockLevel":5,"name":"Clamor de Guerra","kind":"Habilidade","description":"Você e aliados próximos recebem 15% de FOR e não podem ser empurrados durante 2 turnos.","cooldown":"7 turnos","range":"Próprio","area":"Raio 2"}]}'::jsonb),
  ('race', 'tiefling', 'Tiefling', '{"contractVersion":2,"id":"tiefling","name":"Tiefling","epithet":"Herdeiros do Pacto","sigil":"♢","description":"Portadores de poder infernal que convertem risco em magia e dominam áreas perigosas.","baseStats":{"FOR":25,"INT":55,"DEF":30,"RES":48,"HP":430,"INI":11},"powers":[{"id":"tiefling-0","iconUrl":"/assets/skills/races/tiefling/0.webp","unlockLevel":1,"name":"Sangue Infernal","kind":"Característica","description":"Receba 20% menos dano de Fogo. Sempre que perder HP por custo próprio, ganhe uma Barreira igual a 30% do HP gasto."},{"id":"tiefling-1","iconUrl":"/assets/skills/races/tiefling/1.webp","unlockLevel":1,"name":"Chão Profanado","kind":"Habilidade","description":"Cria uma área por 2 turnos. Inimigos que entram ou iniciam o turno nela sofrem 35% da INT como dano mágico.","cooldown":"6 turnos","range":"5","area":"2×2"},{"id":"tiefling-2","iconUrl":"/assets/skills/races/tiefling/2.webp","unlockLevel":5,"name":"Pacto Ardente","kind":"Habilidade","description":"Sacrifique 8% do HP atual para ganhar 25% de dano mágico durante 2 turnos.","cooldown":"6 turnos","range":"Próprio"}]}'::jsonb),
  ('race', 'vampiro', 'Vampiro', '{"contractVersion":2,"id":"vampiro","name":"Vampiro","epithet":"Nobreza da Noite","sigil":"✥","description":"Predadores elegantes que manipulam sangue, sustentam-se em combate e se movem como névoa.","baseStats":{"FOR":45,"INT":48,"DEF":30,"RES":42,"HP":440,"INI":14},"powers":[{"id":"vampiro-0","iconUrl":"/assets/skills/races/vampiro/0.webp","unlockLevel":1,"name":"Sede Carmesim","kind":"Característica","description":"Cure 10% do dano direto causado a inimigos. A cura por rodada não pode ultrapassar 8% do HP máximo."},{"id":"vampiro-1","iconUrl":"/assets/skills/races/vampiro/1.webp","unlockLevel":1,"name":"Dreno Vital","kind":"Habilidade","description":"Causa 65% da INT como dano mágico e cura 50% do dano efetivamente causado.","cooldown":"5 turnos","range":"3","area":"1 alvo"},{"id":"vampiro-2","iconUrl":"/assets/skills/races/vampiro/2.webp","unlockLevel":5,"name":"Forma de Névoa","kind":"Habilidade","description":"Mova-se até 4 células ignorando unidades. Até o próximo turno, não pode ser alvo de ataques de oportunidade e recebe 20% menos dano físico.","cooldown":"6 turnos","range":"4"}]}'::jsonb)
)
update public.v2_content target
set name = source.name,
    payload = source.payload,
    status = 'published',
    published_at = coalesce(target.published_at, now()),
    updated_at = now()
from source
where target.content_type = source.content_type
  and target.slug = source.slug;

-- A migração deve falhar em vez de deixar um catálogo parcialmente trocado.
do $$
begin
  if (select count(*) from public.v2_content where content_type = 'class' and payload->>'contractVersion' = '2') <> 17 then
    raise exception 'Catálogo Rework incompleto: esperado 17 classes';
  end if;
  if (select count(*) from public.v2_content where content_type = 'race' and payload->>'contractVersion' = '2') <> 11 then
    raise exception 'Catálogo Rework incompleto: esperado 11 raças';
  end if;
end $$;
